    11→/// 소스 코드를 LLVM IR로 컴파일하는 헬퍼 함수
    12→fn compileToLLVMIR(source: []const u8, allocator: std.mem.Allocator) ![]const u8 {
    13→    var tokenizer = try Tokenizer.init(source, allocator);
    14→    defer tokenizer.deinit();
    15→
    16→    var tokens = std.ArrayList(Tokenizer.Token).init(allocator);
    17→    defer tokens.deinit();
    18→
    19→    while (try tokenizer.nextToken()) |token| {
    20→        try tokens.append(token);
    21→    }
    22→
    23→    var parser = try Parser.init(tokens.items, source, allocator);
    24→    defer parser.deinit();
    25→    const ast = try parser.parseProgram();
    26→
    27→    var astgen = try AstGen.init(allocator, source);
    28→    defer astgen.deinit();
    29→    try astgen.genProgram(&ast);
    30→
    31→    var sema = try Sema.init(allocator, &astgen.zir);
    32→    defer sema.deinit();
    33→    try sema.analyzeProgram();
    34→
    35→    var llvm_ir = try LLVMIRGen.init(allocator, &sema.air);
    36→    defer llvm_ir.deinit();
    37→    const ir_code = try llvm_ir.generate();
    38→
    39→    return ir_code;
    40→}
